import { hasWalletIds } from './schema.js';
import { walletAddressOf } from './wallets.js';
import { eventFacts, settlementFacts, activityRange } from './facts.js';
import { previousEvents } from './event-store.js';
import { registrationStart } from './positions.js';
import { playerAddress, uint, ZERO_ADDRESS } from './state.js';
import { ChainDataError } from './client.js';
import { flipFromChain, flipToChain } from '../app/token-units.js';
import { encodeBytes32String, solidityPackedKeccak256 } from '../vendor/ethers-app.mjs';

/** Replay Coinflip.bafDrawWinner against the final day's original entry order. */
export function bafWeightedWinner(rows, { day, rngWord, coinflip }) {
  const total = rows.reduce((sum, row) => sum + BigInt(row.args.weight), 0n);
  if (!total) return null;
  const roll = BigInt(solidityPackedKeccak256(
    ['bytes32', 'address', 'uint24', 'uint256'],
    [encodeBytes32String('COINFLIP_BAF_DRAW_WINNER'), coinflip, day, rngWord],
  )) % total;
  let cumulative = 0n;
  for (const row of rows) {
    cumulative += BigInt(row.args.weight);
    if (cumulative > roll) return row.args.player;
  }
  return null;
}

// Coinflip._armBigRecord: a candidate beats `mark` when (candidate - mark) * 5 >= mark, i.e. the bar is
// mark + ceil(mark / 5) in the contract's own units — whole FLIP for the FLIP record (kind 0) since
// audit b05ea7c50, whose values arrive here as token wei. The dice run (kind 4) beats on any rise.
export function recordBarToBeat(kind, value) {
  const mark = BigInt(value ?? 0);
  if (!mark) return 0n;
  if (Number(kind) === 4) return mark + 1n;
  if (Number(kind) !== 0) return mark + (mark + 4n) / 5n;
  const raw = flipToChain(mark);
  return flipFromChain(raw + (raw + 4n) / 5n);
}

export async function bafTopRows(s, level) {
  if (!hasWalletIds()) return Promise.all([0,1,2,3].map(i => s.field('JACKPOTS','bafTop',level,i)));
  const [header, words] = await Promise.all([
    s.field('JACKPOTS','bafLevel',level),
    Promise.all([0,1].map(i => s.field('JACKPOTS','bafTop',level,i))),
  ]);
  return Promise.all(Array.from({length:Number(header.topLen)},async (_,i) => {
    const lane = words[i >> 1] >> BigInt((i & 1) * 128);
    return {player:await walletAddressOf(s,Number((lane >> 96n)&0xffffffffn)) ?? ZERO_ADDRESS,score:lane&((1n<<96n)-1n)};
  }));
}

export async function bafBoard(s, level, signal) {
  const header = await s.field('JACKPOTS', 'bafLevel', level);
  if (!header.epoch && !header.skipped) {
    const top = await bafTopRows(s, level);
    return { entries: top.filter(row => row.player !== ZERO_ADDRESS).map((row, i) => ({ level, player: row.player, score: String(row.score * 10n ** 18n), rank: i + 1 })), scope: 'top-four' };
  }
  const rows = await eventFacts(s, ['BafFlipRecorded'], { contract: 'JACKPOTS', filters: { lvl: level }, fromBlock: await registrationStart(s, level), signal });
  // Replay the four-slot insertion rule: whole-token scores, strict > ties,
  // and the vault excluded. Sorting final raw totals changes tied positions.
  const top=[];
  for(const row of rows){
    const player=row.args.player;if(player===s.client.address('VAULT'))continue;
    const score=BigInt(row.args.newTotal)/10n**18n, capped=score>((1n<<96n)-1n)?(1n<<96n)-1n:score;
    const index=top.findIndex(entry=>entry.player===player);
    if(index>=0){if(capped<=top[index].score)continue;top.splice(index,1);}
    else if(top.length===4){if(capped<=top[3].score)continue;top.pop();}
    let at=top.length;while(at>0&&capped>top[at-1].score)at--;
    top.splice(at,0,{player,score:capped});
  }
  return {entries:top.map((row,i)=>({level,player:row.player,score:String(row.score*10n**18n),rank:i+1})),scope:'top-four'};
}
export async function readBoardRoute(s, url, { signal } = {}) {
  const p = url.pathname.split('/').filter(Boolean); const q = url.searchParams;
  if (url.pathname === '/leaderboards/baf') return bafBoard(s, uint(q.get('level') ?? await s.field('GAME', 'level')), signal);
  if (url.pathname === '/leaderboards/coinflip') {
    const day = uint(q.get('day') ?? s.client.dayAt(s.block.timestamp)); const player = q.has('player') ? playerAddress(q.get('player')) : null;
    const { fromBlock } = await activityRange(s, Math.max(1, day - 1), signal);
    const rows = await eventFacts(s, ['BafDrawEntered'], { contract: 'COINFLIP', day, fromBlock, signal });
    const totals = new Map(); for (const row of rows) totals.set(row.args.player, (totals.get(row.args.player) ?? 0n) + BigInt(row.args.weight));
    const all = [...totals].sort((a,b) => a[1] > b[1] ? -1 : a[1] < b[1] ? 1 : a[0].localeCompare(b[0]))
      .map(([player, score], i) => ({ day, player, score: String(score), rank: i + 1 }));
    return { entries: all.slice(0, 10), totalWeight: String([...totals.values()].reduce((a,b)=>a+b,0n)), totalParticipants: totals.size,
      ...(q.has('rngWord') ? { winner: bafWeightedWinner(rows, { day, rngWord: q.get('rngWord'), coinflip: s.client.address('COINFLIP') }) } : {}),
      player: player ? all.find(row => row.player === player) ?? { day, player, score: '0', rank: null } : null };
  }
  if (url.pathname === '/leaderboards/affiliate') {
    const level = uint(q.get('level') ?? await s.field('GAME', 'level'));
    const top = await s.call('AFFILIATE', 'affiliateTop', [level]);
    const row = { level, player: hasWalletIds() ? await walletAddressOf(s,top.id) ?? ZERO_ADDRESS : top.player.toLowerCase(), score: String(top.score), rank: 1 };
    return { entries: row.player === ZERO_ADDRESS || row.player === s.client.address('VAULT') ? [] : [row], house: row.player === s.client.address('VAULT') ? [row] : [], scope: 'on-chain-leader' };
  }
  if (url.pathname === '/game/coinflip/stats') { const { coinflipStats } = await import('./coinflip-stats.js'); return coinflipStats(s,signal); }
  if (url.pathname === '/records' || url.pathname === '/records/') {
    const methods = ['biggestFlipEver','biggestSpinEver','biggestLuckboxEver','biggestBuyEver','biggestDiceRunEver'];
    const clocks = ['recordDayFlip','recordDaySpin','recordDayLuckbox','recordDayBuy','recordDayDiceRun'];
    const records = await Promise.all(methods.map(async (method, kind) => {
      const [value, clockDay] = await Promise.all([s.call('COINFLIP', method), s.field('COINFLIP', clocks[kind])]);
      // A mark only ever rises, and every BigRecordUpdated sets it to its own strictly higher value
      // (Coinflip._armBigRecord and the dice-run path both return early on candidate <= mark), so
      // the current value names its event: an unchanged value needs no scan. A reorg that undid the
      // event would also change the value back.
      const known = s.client.recordEvents?.get(kind);
      const latest = !value ? null : known?.value === value ? known.latest
        : (await previousEvents(s.client, 'COINFLIP', 'BigRecordUpdated', { blockNumber: s.block.number, logIndex: Number.MAX_SAFE_INTEGER }, { filters: { kind }, signal })).at(-1);
      if (value && latest && BigInt(latest.args.value) === BigInt(value)) { s.client.recordEvents ??= new Map(); s.client.recordEvents.set(kind, { value, latest }); }
      return { kind, player: latest?.args.player.toLowerCase() ?? null, value: String(value), barToBeat: String(recordBarToBeat(kind, value)),
        totalPaidFlip: null, totalPaidSdgnrs: null, claimCount: null, blockNumber: latest?.blockNumber ?? null, lastClaimBlock: latest?.args.paid ? latest.blockNumber : null,
        clockDay: Number(clockDay), transactionHash: latest?.transactionHash ?? null, logIndex: latest?.logIndex ?? null };
    }));
    return { recordPool: String(await s.call('COINFLIP', 'recordPool')), poolBlockNumber: s.block.number, records: records.slice(0,4), diceRun: records[4] };
  }
  if (p[0] === 'game' && p[1] === 'parimutuel' && p[4] === 'winners') {
    if (p[2] !== 'growth') throw new ChainDataError('Unknown market.', 'INVALID_REQUEST');
    const round = uint(p[3]); const over = q.get('over') === '1' || q.get('over') === 'true';
    const fromBlock = await registrationStart(s, round);
    const rows = await eventFacts(s, ['BetPlaced', hasWalletIds() ? 'GrowthWinnersPaid' : 'BetClaimed', 'GrowthRoundSealed'], { contract: 'PARIMUTUEL', filters: { round }, fromBlock, signal });
    const claims = new Map(rows.filter(e => e.name === 'BetClaimed').map(e => [e.args.player, e.args.payout]));
    const seal = rows.find(e => e.name === 'GrowthRoundSealed');
    const bets = rows.filter(e => e.name === 'BetPlaced' && e.args.over === over);
    // Automatic settlement pays contiguous positions in each side's insertion
    // order. A sealed round may still have unpaid positions while work continues.
    if (hasWalletIds()) for (const paid of rows.filter(e => e.name === 'GrowthWinnersPaid' && Number(e.args.outcome) === (over ? 1 : 2))) {
      const start = Number(paid.args.firstIndex), end = start + Number(paid.args.count);
      for (const bet of bets.slice(start, end)) claims.set(bet.args.player, paid.args.payout);
    }
    return { market: 'growth', round, over, sealed: seal ? seal.args.over === over : null,
      winners: bets.map(e => ({ player: e.args.player, credit: claims.get(e.args.player) ?? null,
        blockNumber: e.blockNumber, logIndex: e.logIndex, transactionHash: e.transactionHash })) };
  }
  return undefined;
}
